<?php
$root=dirname(__DIR__);$csv=$root.'/database/seeds/global_learning_base.csv';$seed=$root.'/database/seeds/011_global_learning_library.sql';if(!is_file($csv)||!is_file($seed)){fwrite(STDERR,"Missing global learning seed source\n");exit(1);} $h=fopen($csv,'rb');$header=fgetcsv($h);$header[0]=preg_replace('/^\xEF\xBB\xBF/','',$header[0]);$idx=array_flip($header);$count=0;$types=[];$terms=[];while(($r=fgetcsv($h))!==false){$count++;$type=trim((string)$r[$idx['card_type']]);$term=trim((string)$r[$idx['term']]);$key=$type.'|'.strtolower(preg_replace('/\s+/u',' ',$term));if(isset($terms[$key])){fwrite(STDERR,"Duplicate base item: $key\n");exit(1);}$terms[$key]=1;$types[$type]=($types[$type]??0)+1;}fclose($h);if($count!==804){fwrite(STDERR,"Expected 804 base items, got $count\n");exit(1);}foreach(['VOCABULARY'=>264,'COLLOCATION'=>200,'LISTENING'=>340] as $k=>$n)if(($types[$k]??0)!==$n){fwrite(STDERR,"Unexpected $k count\n");exit(1);} $all='';foreach(new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS)) as $f){if($f->isFile()&&preg_match('/\.(php|sql|md|json|js|csv)$/i',$f->getFilename()))$all.=@file_get_contents($f->getPathname());}if(preg_match('/[A-Z0-9._%+-]+@(gmail|yahoo|outlook|hotmail)\.[A-Z]{2,}/i',$all)){fwrite(STDERR,"Personal-style email remains in project\n");exit(1);}echo "GLOBAL BASE SEED PASS: $count items; ".json_encode($types,JSON_UNESCAPED_UNICODE)."\n";
